        return instanceMapper.findByFilters(user.getId(), dbType, groupId, isAdmin);
    }

    public Instance updateInstance(Long id, com.dbconsole.platform.dto.UpdateInstanceRequest req, User user) {
        Instance instance = getInstance(id, user);
        if (instance == null) {
            return null;
        }
        if (req.getName() != null) {
            instance.setName(req.getName());
        }
        if (req.getHost() != null) {
            instance.setHost(req.getHost());
        }
        if (req.getPort() != null) {
            instance.setPort(req.getPort());
        }
        if (req.getSchemaName() != null) {
            instance.setSchemaName(req.getSchemaName());
        }
        if (req.getAccount() != null) {
            instance.setAccount(req.getAccount());
        }
        if (req.getPassword() != null) {
            instance.setPassword(req.getPassword());
        }
        if (req.getGroupId() != null) {
            instance.setGroupId(req.getGroupId());
        }
        instance.setUpdatedAt(LocalDateTime.now());
        instanceMapper.update(instance);
        return instance;
    }

    public boolean deleteInstance(Long id, User user) {
        Instance instance = getInstance(id, user);
        if (instance == null) {
            return false;
        }
        instanceMapper.deleteById(id);
        return true;
    }

    public Map<String, Object> ping(Long id, User user) {
        Instance instance = getInstance(id, user);
        if (instance == null) {
            return null;
        }

        String dbType = instance.getDbType();
        if (dbType == null) {
            return unreachable("不支持的实例类型");
        }

        return switch (dbType.toUpperCase()) {
            case "MYSQL", "REDIS" -> pingTcp(instance.getHost(), instance.getPort());
            case "OSS" -> pingOss(instance.getHost(), instance.getSchemaName());
            default -> unreachable("不支持的实例类型");
        };
    }

    private Map<String, Object> pingTcp(String host, Integer port) {
        if (host == null || port == null) {
            return unreachable("主机或端口为空");
        }
        long start = System.currentTimeMillis();
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(host, port), TIMEOUT_MS);
            long latency = System.currentTimeMillis() - start;
            return reachable(latency, "连接成功");
        } catch (IOException e) {
            return unreachable("连接超时");
        }
    }

    private Map<String, Object> pingOss(String host, String schemaName) {
        if (host == null) {
            return unreachable("连接超时");
        }
        String path = schemaName != null ? schemaName : "";
        String url = "http://" + host + "/" + path;
        long start = System.currentTimeMillis();
        try {
            HttpURLConnection conn = (HttpURLConnection) URI.create(url).toURL().openConnection();
            conn.setConnectTimeout(TIMEOUT_MS);
            conn.setReadTimeout(TIMEOUT_MS);
            conn.setRequestMethod("GET");
            int statusCode = conn.getResponseCode();
            long latency = System.currentTimeMillis() - start;
            conn.disconnect();
            return reachable(latency, "连接成功，状态码: " + statusCode);
        } catch (IOException e) {
            return unreachable("连接超时");
        }
    }

    private static Map<String, Object> reachable(long latency, String detail) {
        Map<String, Object> result = new HashMap<>();
        result.put("reachable", true);
        result.put("latencyMs", latency);
        result.put("detail", detail);
        return result;
    }

    private static Map<String, Object> unreachable(String detail) {
        Map<String, Object> result = new HashMap<>();
        result.put("reachable", false);
        result.put("latencyMs", null);
        result.put("detail", detail);
        return result;
    }
