package com.dbconsole.platform.config;

import com.dbconsole.platform.entity.Instance;
import com.dbconsole.platform.entity.InstanceGroup;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.InstanceGroupMapper;
import com.dbconsole.platform.mapper.InstanceMapper;
import com.dbconsole.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final InstanceGroupMapper groupMapper;
    private final InstanceMapper instanceMapper;

    public DataInitializer(UserMapper userMapper,
                           InstanceGroupMapper groupMapper,
                           InstanceMapper instanceMapper) {
        this.userMapper = userMapper;
        this.groupMapper = groupMapper;
        this.instanceMapper = instanceMapper;
    }

    @Override
    public void run(String... args) {
        seedUsers();
        seedGroups();
        seedInstances();
    }

    private void seedUsers() {
        if (userMapper.countAll() == 0) {
            LocalDateTime now = LocalDateTime.now();

            User admin = new User();
            admin.setUsername("admin");
            admin.setPassword("admin123");
            admin.setRole("ADMIN");
            admin.setCreatedAt(now);
            userMapper.insert(admin);

            User user1 = new User();
            user1.setUsername("user1");
            user1.setPassword("user123");
            user1.setRole("USER");
            user1.setCreatedAt(now);
            userMapper.insert(user1);

            User user2 = new User();
            user2.setUsername("user2");
            user2.setPassword("user123");
            user2.setRole("USER");
            user2.setCreatedAt(now);
            userMapper.insert(user2);
        }
    }

    private void seedGroups() {
        if (groupMapper.countAll() == 0) {
            LocalDateTime now = LocalDateTime.now();

            User admin = userMapper.findByUsername("admin");
            if (admin != null) {
                InstanceGroup group1 = new InstanceGroup();
                group1.setName("默认分组");
                group1.setDescription("默认实例分组");
                group1.setOwnerId(admin.getId());
                group1.setCreatedAt(now);
                groupMapper.insert(group1);
            }

            User user1 = userMapper.findByUsername("user1");
            if (user1 != null) {
                InstanceGroup group2 = new InstanceGroup();
                group2.setName("测试环境");
                group2.setDescription("测试环境实例");
                group2.setOwnerId(user1.getId());
                group2.setCreatedAt(now);
                groupMapper.insert(group2);
            }
        }
    }

    private void seedInstances() {
        if (instanceMapper.countAll() == 0) {
            LocalDateTime now = LocalDateTime.now();

            InstanceGroup firstGroup = groupMapper.findById(1L);
            User user1 = userMapper.findByUsername("user1");

            if (firstGroup != null && user1 != null) {
                Instance instance = new Instance();
                instance.setName("内部MySQL");
                instance.setDbType("MYSQL");
                instance.setHost("mysql.internal.com");
                instance.setPort(3306);
                instance.setSchemaName("app_db");
                instance.setAccount("root");
                instance.setStatus("CREATED");
                instance.setGroupId(firstGroup.getId());
                instance.setOwnerId(user1.getId());
                instance.setCreatedAt(now);
                instance.setUpdatedAt(now);
                instanceMapper.insert(instance);
            }
        }
    }
}

package com.dbconsole.platform.config;

import com.dbconsole.platform.security.JwtAuthenticationFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtFilter) {
        this.jwtFilter = jwtFilter;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login").permitAll()
                        .anyRequest().authenticated()
                )
                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }
}

